/* Project any latitude/longitude into the same 520x760 viewBox.
   Lambert conformal conic, standard parallels 50/58, central meridian -4.4, with the
   scale and translate that d3 fitExtent worked out baked in as constants. */
window.UK_MAP.project = (function () {
  var N = 0.809677033714821;          // cone constant
  var F = 1.79949465818943;          // r at the equator
  var K = 3870.22518877148;          // projection scale
  var TX = 210.024169104314, TY = 4636.04214275807;  // projection translate
  var ROT = 4.4;            // d3 rotate[0]
  var DEG = Math.PI / 180, HALF_PI = Math.PI / 2, TWO_PI = Math.PI * 2;
  return function (lat, lon) {
    var lambda = (lon + ROT) * DEG;
    while (lambda > Math.PI) lambda -= TWO_PI;
    while (lambda < -Math.PI) lambda += TWO_PI;
    var phi = lat * DEG;
    var r = F / Math.pow(Math.tan((HALF_PI + phi) / 2), N);
    var x = r * Math.sin(N * lambda);
    var y = F - r * Math.cos(N * lambda);
    return {
      x: Math.round((x * K + TX) * 10) / 10,
      y: Math.round((TY - y * K) * 10) / 10
    };
  };
}());
